:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --border-radius: 12px;
  --font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-family);
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.score {
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--accent);
  padding: 4px 12px;
  border-radius: 20px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0b0b1a;
  border-radius: var(--border-radius);
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--primary);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  max-width: 280px;
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  padding: 12px 24px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-width: 120px;
}

.btn:hover {
  background: #1a4a7a;
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #ff5a7a;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .btn {
  flex: 1;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score {
    font-size: 1rem;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.9rem;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlayTitle');
const overlayText = document.getElementById('overlayText');
const startBtn = document.getElementById('startBtn');
const pauseBtn = document.getElementById('pauseBtn');
const restartBtn = document.getElementById('restartBtn');

const GRID_SIZE = 20;
const CELL_SIZE = canvas.width / GRID_SIZE;
const TICK_INTERVAL = 150;

let snake = [];
let direction = { x: 0, y: 0 };
let nextDirection = { x: 0, y: 0 };
let food = { x: 0, y: 0 };
let score = 0;
let gameState = 'paused'; // 'paused', 'running', 'gameover'
let lastTick = 0;
let accumulator = 0;
let gameLoopId = null;
let isInitialLoad = true;

function resetGame() {
  snake = [{ x: 10, y: 10 }];
  direction = { x: 0, y: 0 };
  nextDirection = { x: 0, y: 0 };
  score = 0;
  scoreEl.textContent = '0';
  gameState = 'paused';
  placeFood();
  draw();
  if (isInitialLoad) {
    overlayTitle.textContent = 'How to Play';
    overlayText.innerHTML = 'Use arrow keys to move the snake.<br>Eat the red food to grow and score points.<br>Avoid hitting walls or yourself!';
    startBtn.textContent = 'Start Game';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  } else {
    updateOverlay();
  }
  if (gameLoopId) {
    cancelAnimationFrame(gameLoopId);
    gameLoopId = null;
  }
}

function placeFood() {
  let newFood;
  let attempts = 0;
  do {
    newFood = {
      x: Math.floor(Math.random() * GRID_SIZE),
      y: Math.floor(Math.random() * GRID_SIZE)
    };
    attempts++;
  } while (snake.some(seg => seg.x === newFood.x && seg.y === newFood.y) && attempts < 1000);
  food = newFood;
}

function updateOverlay() {
  if (gameState === 'paused') {
    overlayTitle.textContent = 'Paused';
    overlayText.innerHTML = 'Press Start or Space to resume.<br>Use arrow keys to move.';
    startBtn.textContent = 'Resume';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Resume';
    pauseBtn.setAttribute('aria-label', 'Resume game');
  } else if (gameState === 'gameover') {
    overlayTitle.textContent = 'Game Over';
    overlayText.innerHTML = `Your score: ${score}<br>Press Restart to play again.`;
    startBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  } else {
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.setAttribute('aria-label', 'Pause game');
  }
}

function startGame() {
  if (gameState === 'gameover') {
    resetGame();
  }
  if (gameState === 'paused') {
    gameState = 'running';
    isInitialLoad = false;
    updateOverlay();
    lastTick = performance.now();
    accumulator = 0;
    if (!gameLoopId) {
      gameLoopId = requestAnimationFrame(gameLoop);
    }
  }
}

function pauseGame() {
  if (gameState === 'running') {
    gameState = 'paused';
    updateOverlay();
    if (gameLoopId) {
      cancelAnimationFrame(gameLoopId);
      gameLoopId = null;
    }
  } else if (gameState === 'paused') {
    startGame();
  }
}

function gameOver() {
  gameState = 'gameover';
  updateOverlay();
  if (gameLoopId) {
    cancelAnimationFrame(gameLoopId);
    gameLoopId = null;
  }
}

function gameLoop(timestamp) {
  if (gameState !== 'running') return;
  const delta = timestamp - lastTick;
  lastTick = timestamp;
  accumulator += delta;
  while (accumulator >= TICK_INTERVAL) {
    accumulator -= TICK_INTERVAL;
    tick();
    if (gameState !== 'running') return;
  }
  draw();
  gameLoopId = requestAnimationFrame(gameLoop);
}

function tick() {
  if (nextDirection.x !== 0 || nextDirection.y !== 0) {
    if (direction.x !== -nextDirection.x || direction.y !== -nextDirection.y) {
      direction = { ...nextDirection };
    }
  }
  if (direction.x === 0 && direction.y === 0) return;

  const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

  if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
    gameOver();
    return;
  }

  if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
    gameOver();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = score;
    placeFood();
  } else {
    snake.pop();
  }
}

function draw() {
  ctx.fillStyle = '#0b0b1a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw food
  ctx.fillStyle = '#e94560';
  ctx.fillRect(food.x * CELL_SIZE, food.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

  // Draw snake
  snake.forEach((seg, i) => {
    ctx.fillStyle = i === 0 ? '#eaeaea' : '#0f3460';
    ctx.fillRect(seg.x * CELL_SIZE, seg.y * CELL_SIZE, CELL_SIZE - 1, CELL_SIZE - 1);
  });
}

function handleKey(e) {
  const key = e.key;
  if (key === ' ' || key === 'Space') {
    e.preventDefault();
    if (gameState === 'paused') startGame();
    else if (gameState === 'running') pauseGame();
    else if (gameState === 'gameover') {
      resetGame();
      startGame();
    }
    return;
  }
  if (gameState !== 'running') return;
  if (key === 'ArrowUp' && direction.y === 0) nextDirection = { x: 0, y: -1 };
  else if (key === 'ArrowDown' && direction.y === 0) nextDirection = { x: 0, y: 1 };
  else if (key === 'ArrowLeft' && direction.x === 0) nextDirection = { x: -1, y: 0 };
  else if (key === 'ArrowRight' && direction.x === 0) nextDirection = { x: 1, y: 0 };
  else return;
  e.preventDefault();
}

function restart() {
  resetGame();
  startGame();
}

startBtn.addEventListener('click', startGame);
pauseBtn.addEventListener('click', pauseGame);
restartBtn.addEventListener('click', restart);
window.addEventListener('keydown', handleKey);

// Initialize
resetGame();
